contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    receive() external payable {}
    fallback() external payable {}
    function test(uint256 seedAmt, uint256 sendAmt) public {
        require(address(this).balance >= seedAmt + sendAmt);
        // Give c some leftover ether via its fallback
