contract InvMutTest {
    C c;
    uint256 received;
    uint256 constant PREFUND = 1;

    constructor(C _c) {
        c = _c;
        // fund c's reserve via its payable fallback
        (bool ok, ) = address(c).call{value: PREFUND}("");
        require(ok);
    }

    function t(uint256 amount) public {
        require(address(this).balance >= amount);
        c.go{value: amount}();
        // In P, owner receives exactly the pre-existing reserve (msg.value
        // was already forwarded to the target before the transfer).
        // In M, the transfer happens before the call, so owner would also
        // receive msg.value.
        assert(received == PREFUND);
    }

    receive() external payable {
        received += msg.value;
    }
}

